practiceProblems.solutionCode:
public class Main {
    public static int sumToN(int n) {
        if (n <= 1) {
            return 1;
        }
        return n + sumToN(n - 1);
    }

    public static void main(String[] args) {
        int total = sumToN(5);
        System.out.println("Sum 1..5: " + total);
    }
}

