practiceProblems.solutionCode:
public class Main {
    public static int power(int base, int exp) {
        if (exp == 0) {
            return 1;
        }
        return base * power(base, exp - 1);
    }

    public static void main(String[] args) {
        System.out.println("2^6 = " + power(2, 6));
    }
}

