practiceProblems.solutionCode:
public class Main {
    public static int sumOfDigits(int n) {
        if (n < 10) {
            return n;
        }
        return (n % 10) + sumOfDigits(n / 10);
    }

    public static void main(String[] args) {
        int sum = sumOfDigits(12345);
        System.out.println("Sum of digits: " + sum);
    }
}

